if (!$json.invoice_id) throw new Error('invoice_id is required');
if (!$json.pdf_path) throw new Error('pdf_path is required');
if (!$json.target_chat_id) throw new Error('target_chat_id is required');
return [{ json: { ...$json, delivery_status: 'pending' } }];

const invoiceId = $json.invoice_id;
const invoiceNumber = $json.invoice_number || $json.render_request?.invoice?.invoice_number || null;
const targetChatId = $json.target_chat_id;
const pdfPath = $json.pdf_path || $json.render_response?.file_path || null;

if (!invoiceId) {
  throw new Error('invoice_id is required');
}
if (!targetChatId || String(targetChatId).trim() === '') {
  throw new Error('target_chat_id is required');
}
if (!pdfPath || String(pdfPath).trim() === '') {
  throw new Error('pdf_path is required');
}
if (!String(pdfPath).toLowerCase().endsWith('.pdf')) {
  throw new Error('pdf_path must point to a PDF file');
}

const caption = invoiceNumber
  ? `Invoice ${invoiceNumber} - STA Transport`
  : 'Invoice STA Transport';

return [
  {
    json: {
      ...$json,
      invoice_id: Number(invoiceId),
      target_chat_id: String(targetChatId),
      pdf_path: String(pdfPath),
      telegram_method: 'sendDocument',
      telegram_document_payload: {
        chat_id: String(targetChatId),
        document_path: String(pdfPath),
        caption,
      },
      delivery_status: 'sending',
      delivery_payload_ready: true,
    },
  },
];

const response = $json.telegram_response || $json;
const ok = response.ok === true && response.result && response.result.message_id;
const errorCode = response.error_code ?? $json.http_status ?? null;
const redactSensitive = (value) => String(value).replace(
  /(token|password|api[_-]?key|authorization)=\S+/gi,
  '$1=[redacted]',
);
const sanitizeValue = (value) => {
  if (typeof value === 'string') return redactSensitive(value);
  if (Array.isArray(value)) return value.map(sanitizeValue);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, sanitizeValue(item)]));
  }
  return value;
};
const sanitizedResponse = sanitizeValue(response);

return [
  {
    json: {
      ...$json,
      delivery_status: ok ? 'sent' : 'failed',
      provider_message_id: ok ? String(response.result.message_id) : null,
      http_status: $json.http_status ?? response.http_status ?? null,
      provider_error_code: ok || errorCode === null ? null : String(errorCode),
      provider_error_message: ok ? null : redactSensitive(response.description || 'Telegram delivery failed'),
      provider_response: sanitizedResponse,
    },
  },
];
